matched_products as (
  select
    p.id,
    c.slug,
    c.file_base,
    c.name_pt,
    c.description_pt,
    c.price,
    c.category,
    c.categories,
    c.image_url,
    c.sort_order
  from products p
  join catalog c
    on p.slug = c.slug
    or p.slug = c.file_base
    or regexp_replace(coalesce(p.image_url, ''), '^.*/([^/.]+)\.[^/.]+$', '\1') = c.file_base
),
updated as (
  update products p
  set
    name_pt = m.name_pt,
    description_pt = m.description_pt,
    price = m.price,
    category = m.category,
    categories = m.categories,
    image_url = m.image_url,
    is_visible = true,
    sort_order = m.sort_order,
    updated_at = now()
  from matched_products m
  where p.id = m.id
  returning p.id
)
insert into products (
  slug,
  name_pt,
  description_pt,
  price,
  category,
  categories,
  image_url,
  is_visible,
  sort_order
)
select
  c.slug,
  c.name_pt,
  c.description_pt,
  c.price,
  c.category,
  c.categories,
  c.image_url,
  true,
  c.sort_order
from catalog c
where not exists (
  select 1
  from products p
  where p.slug = c.slug
     or p.slug = c.file_base
     or regexp_replace(coalesce(p.image_url, ''), '^.*/([^/.]+)\.[^/.]+$', '\1') = c.file_base
)
on conflict (slug) do update
set
  name_pt = excluded.name_pt,
  description_pt = excluded.description_pt,
  price = excluded.price,
  category = excluded.category,
  categories = excluded.categories,
  image_url = excluded.image_url,
  is_visible = true,
  sort_order = excluded.sort_order,
  updated_at = now();

